<script setup>
import { computed, reactive } from 'vue';
import { Head, Link, router } from '@inertiajs/vue3';

const props = defineProps({ organization: Object, currentBranch: Object, shifts: Object, filters: Object, summary: Object });
const form = reactive({ from: props.filters?.from || '', to: props.filters?.to || '', status: props.filters?.status || '' });
const query = computed(() => Object.fromEntries(Object.entries(form).filter(([, value]) => value !== '')));
function filterShifts() { router.get('/pos/shifts/history', query.value, { preserveState: true, replace: true }); }
function exportUrl() {
    const params = new URLSearchParams(query.value).toString();
    return `/pos/shifts/history/export${params ? `?${params}` : ''}`;
}
function money(value) { return Number(value || 0).toLocaleString('ar-EG', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
function statusLabel(status) { return status === 'open' ? 'مفتوحة' : 'مغلقة'; }
</script>

<template>
    <Head title="سجل الورديات والتسويات" />
    <main dir="rtl" class="min-h-screen space-y-6 bg-slate-950 p-4 text-slate-100 sm:p-6 lg:p-8">
        <header class="flex flex-wrap items-start justify-between gap-4"><div><p class="text-sm font-semibold text-emerald-300">{{ organization?.name }} · {{ currentBranch?.name }}</p><h1 class="mt-2 text-3xl font-black">سجل الورديات والتسويات</h1><p class="mt-2 text-sm text-slate-400">مراجعة النقدية الافتتاحية والمتوقعة والفعلية والفرق، لكل وردية داخل الفرع المحدد.</p></div><div class="flex gap-2"><a :href="exportUrl()" class="rounded-xl border border-white/10 px-4 py-3 text-sm font-bold hover:bg-white/5">تصدير CSV</a><Link href="/pos" class="rounded-xl bg-emerald-300 px-4 py-3 text-sm font-bold text-slate-950">العودة لنقطة البيع</Link></div></header>
        <section class="grid gap-3 sm:grid-cols-3"><article class="rounded-2xl border border-white/10 bg-slate-900 p-5"><p class="text-sm text-slate-400">إجمالي الورديات</p><strong class="mt-2 block text-3xl">{{ summary?.total ?? 0 }}</strong></article><article class="rounded-2xl border border-emerald-300/20 bg-emerald-300/5 p-5"><p class="text-sm text-slate-400">ورديات مفتوحة</p><strong class="mt-2 block text-3xl text-emerald-200">{{ summary?.open ?? 0 }}</strong></article><article class="rounded-2xl border border-white/10 bg-slate-900 p-5"><p class="text-sm text-slate-400">ورديات مغلقة</p><strong class="mt-2 block text-3xl">{{ summary?.closed ?? 0 }}</strong></article></section>
        <form class="grid gap-3 rounded-2xl border border-white/10 bg-slate-900 p-4 md:grid-cols-[1fr_1fr_1fr_auto] md:items-end" @submit.prevent="filterShifts"><label class="text-sm">من تاريخ<input v-model="form.from" type="date" class="mt-2 w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-3" /></label><label class="text-sm">إلى تاريخ<input v-model="form.to" type="date" class="mt-2 w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-3" /></label><label class="text-sm">الحالة<select v-model="form.status" class="mt-2 w-full rounded-xl border border-white/10 bg-slate-950 px-3 py-3"><option value="">كل الحالات</option><option value="open">مفتوحة</option><option value="closed">مغلقة</option></select></label><button class="rounded-xl bg-emerald-300 px-5 py-3 font-bold text-slate-950">تطبيق الفلاتر</button></form>
        <section class="overflow-x-auto rounded-2xl border border-white/10 bg-slate-900"><table class="w-full min-w-[920px] text-right text-sm"><thead class="bg-white/5 text-slate-400"><tr><th class="p-4">رقم الوردية</th><th class="p-4">الكاشير</th><th class="p-4">البداية</th><th class="p-4">النهاية</th><th class="p-4">الافتتاحي</th><th class="p-4">المتوقع</th><th class="p-4">الفعلي</th><th class="p-4">الفرق</th><th class="p-4">الحالة</th><th class="p-4">التقرير</th></tr></thead><tbody><tr v-for="shift in shifts?.data || []" :key="shift.id" class="border-t border-white/5"><td class="p-4 font-bold">#{{ shift.id }}</td><td class="p-4">{{ shift.cashierName || '—' }}</td><td class="p-4 text-slate-400">{{ shift.openedAt || '—' }}</td><td class="p-4 text-slate-400">{{ shift.closedAt || '—' }}</td><td class="p-4">{{ money(shift.openingAmount) }}</td><td class="p-4">{{ money(shift.expectedCash) }}</td><td class="p-4">{{ shift.closingAmount === null ? '—' : money(shift.closingAmount) }}</td><td class="p-4" :class="Number(shift.differenceAmount || 0) < 0 ? 'text-rose-300' : Number(shift.differenceAmount || 0) > 0 ? 'text-amber-200' : 'text-emerald-200'">{{ shift.differenceAmount === null ? '—' : money(shift.differenceAmount) }}</td><td class="p-4"><span class="rounded-full px-3 py-1 text-xs" :class="shift.status === 'open' ? 'bg-emerald-300/10 text-emerald-200' : 'bg-white/5 text-slate-300'">{{ statusLabel(shift.status) }}</span></td><td class="p-4"><Link :href="`/pos/shifts/${shift.id}/report`" class="font-bold text-emerald-200 underline underline-offset-4">فتح</Link></td></tr><tr v-if="!(shifts?.data || []).length"><td colspan="10" class="p-8 text-center text-slate-500">لا توجد ورديات في الفترة المحددة.</td></tr></tbody></table></section>
        <nav v-if="shifts?.links?.length" class="flex flex-wrap gap-2"><template v-for="link in shifts.links" :key="`${link.label}-${link.url}`"><Link v-if="link.url" :href="link.url" preserve-scroll class="rounded-lg border px-3 py-2 text-sm" :class="link.active ? 'border-emerald-300 bg-emerald-300 text-slate-950' : 'border-white/10 text-slate-300'" v-html="link.label" /><span v-else class="rounded-lg border border-white/5 px-3 py-2 text-sm text-slate-600" v-html="link.label" /></template></nav>
    </main>
</template>
